#!/bin/bash
set -e
perl -0pi -e 's/^mod producer;/mod payload;\nmod producer;/m' mod.rs
perl -0pi -e 's/    Producer\(producer::Input\),/    Payload(payload::Input),\n    Producer(producer::Input),/' mod.rs
perl -0pi -e 's/(        if args.first\(\).is_some_and\(\|arg\| arg == "artifacts"\) \{)/        if args.first().is_some_and(|arg| arg == "payload") {\n            return Ok(Self::Payload(payload::Input::parse(&args[1..])?));\n        }\n$1/' mod.rs
perl -0pi -e 's/(        if let Self::Producer\(input\) = self \{\n            return Ok\(Some\(input.execute\(client\).await\?\)\);\n        \}\n)/$1        if let Self::Payload(input) = self {\n            return Ok(Some(input.execute(client).await?));\n        }\n/' mod.rs
perl -0pi -e 's/(    " \| artifacts STORE_ID)/    " | payload STORE_ID PAYLOAD_ID [--cursor CURSOR] [--page-size N]",\n$1/' mod.rs
perl -0pi -e 's/(                "producer_stream_get" => Self::Query\(Command::Producer)/                "payload_lookup" => Self::Query(Command::Payload(super::payload::Input {\n                    store: fields.required("store_id")?,\n                    payload_id: fields.required("payload_id")?,\n                    cursor: fields.optional("cursor")?,\n                    page_size: fields\n                        .raw("page_size")?\n                        .map(u32::from_json)\n                        .transpose()?\n                        .unwrap_or(200),\n                })),\n$1/' tool.rs
perl -0pi -e 's/(    \(\n        "producer_stream_get",)/    (\n        "payload_lookup",\n        "Read which held artifacts carry one payload id (blake3: and the 64-hex digest of an artifact\x27s bytes), one page by artifact id. answer_certainty is exact once the payload-index migration is complete; while it runs, every listed artifact is held and an unlisted one is unknown, not absent. An artifact leaves the index when it is evicted or its entry is deleted.",\n    ),\n$1/' tool/catalog.rs
perl -0pi -e 's/(        if \*name == "producer_stream_get" \{)/        if *name == "payload_lookup" {\n            properties = properties\n                .with("store_id", string())\n                .with("payload_id", string())\n                .with("page_size", integer(1000))\n                .with(\n                    "cursor",\n                    Object::new().with("type", Value::array(["string", "null"])),\n                );\n            required.extend(["store_id", "payload_id"]);\n        }\n$1/' tool/catalog.rs
